/**
 * Finds the page for a URL and resolves it the way v7 rendered it: every section, then v7's
 * section loaders (/next/tanstack-start-descriptors#3-match-the-url-to-a-page).
 * Generated by the deco-v7-to-v8-migration skill; it's your code now.
 */
import { matchRoute, type Route } from "@decocms/blocks";
import { requestDevice } from "@decocms/compat-v7/tanstack/server";
import { DEGRADED_HEADER } from "@decocms/tanstack/server";
import { notFound, redirect } from "@tanstack/react-router";
import { setResponseHeader } from "@tanstack/react-start/server";
import { type BlockDescriptor, loadSections, matchPage, type PageSeo } from "../.deco";
import { client } from "./cms";

/** A page as saved: its sections and SEO are still blocks. */
interface StoredPage extends Route {
  sections?: unknown;
  seo?: unknown;
}

/**
 * The SEO defaults v7 applied to every page: the seo of the saved site block (getSiteSeo). The script
 * read them once; they are code now.
 */
const SITE_SEO: PageSeo = {
  title: "Storefront",
  description: "Build profitable websites with deco.cx",
  image: "https://decoims.com/storefront-tanstack/bfe00763-d6fa-40f0-9fa9-77e6769fe02d/1742560188441-74d13a55-4c18-4a5c-8cb4-dcaa27aae923.png",
  titleTemplate: "%s | deco.cx",
  descriptionTemplate: "%s | deco.cx",
};

/** v7's template rule: blank or "%s" is no template. */
function template(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() !== "" && value.trim() !== "%s" ? value : undefined;
}

/**
 * The page's SEO as v7 built it (buildPageSeo): the page's SEO block's fields (or a section descriptor
 * carrying them), the site's defaults for an empty title, description and image, then the block's
 * title and description templates, else the site's.
 */
function seoFields(seo: unknown): PageSeo {
  const fields = seo && typeof seo === "object" && "props" in seo ? (seo as { props: unknown }).props : seo;
  const props = (fields && typeof fields === "object" ? fields : {}) as Record<string, unknown>;
  const out: PageSeo = {};
  if (props.title) out.title = props.title as string;
  if (props.description) out.description = props.description as string;
  if (props.canonical) out.canonical = props.canonical as string;
  if (props.image) out.image = props.image as string;
  if (props.noIndexing !== undefined) out.noIndexing = props.noIndexing as boolean;
  if (props.type) out.type = props.type as string;
  if (Array.isArray(props.jsonLDs) && props.jsonLDs.length) out.jsonLDs = props.jsonLDs;
  if (!out.title && SITE_SEO.title) out.title = SITE_SEO.title;
  if (!out.description && SITE_SEO.description) out.description = SITE_SEO.description;
  if (!out.image && SITE_SEO.image) out.image = SITE_SEO.image;
  const titleTemplate = template(props.titleTemplate) ?? template(SITE_SEO.titleTemplate);
  const descriptionTemplate = template(props.descriptionTemplate) ?? template(SITE_SEO.descriptionTemplate);
  if (titleTemplate && out.title) out.title = titleTemplate.replace("%s", out.title);
  if (descriptionTemplate && out.description) {
    out.description = descriptionTemplate.replace("%s", out.description);
  }
  return out;
}

/**
 * Opens the page at `href` (a path on this site, with its query) for `request`. Every read uses the
 * page's URL, never the request's: on a client-side navigation the request is the server-function
 * call (/_serverFn/…), and v7 matched and loaded the page being opened.
 */
export async function openPage(href: string, request: Request) {
  const url = new URL(href, request.url);
  if (url.origin !== new URL(request.url).origin) throw notFound();
  // v7's matchers read this page, not the server-function call.
  matchPage(url, request);
  const c = await client(request);
  // Routing reads the index: the pages' paths, then the redirects block.
  const [routes, routesError] = await c.routes();
  if (routesError) throw routesError;
  const match = matchRoute(url, { routes });
  // The page's blocks start downloading with the redirects block, in one wave.
  if (match.kind === "match") c.prefetch(match.entry.name);
  const [redirects, redirectsError] = await c.redirects();
  if (redirectsError) throw redirectsError;
  const moved = matchRoute(url, { routes: [], redirects });
  if (moved.kind === "redirect") throw redirect({ href: moved.location, statusCode: moved.status });
  if (match.kind !== "match") throw notFound();

  const [page, pageError] = await c.resolve<StoredPage>(match.entry.name, { run: false });
  if (pageError) throw pageError;
  // Variants of the whole list are one multivariate block: it resolves to the chosen list.
  const saved = Array.isArray(page.sections) ? page.sections : page.sections ? [page.sections] : [];
  const resolved = await Promise.all(
    saved.map(async (block) => {
      const [value, error] = await c.resolve<BlockDescriptor | BlockDescriptor[] | undefined>(block);
      if (error) console.error(error); // a failed section renders nothing
      return value ?? [];
    }),
  );
  // v7's section loaders, as v7 ran them once the page resolved, at the page's URL.
  const { sections, degraded } = await loadSections(resolved.flat(), request, url);

  const [seo, seoError] = await c.resolve<unknown>(page.seo);
  if (seoError) throw seoError;
  // A section whose loader failed kept its saved props: v7 sent this header, and the worker never
  // caches the page.
  if (degraded.length > 0) setResponseHeader(DEGRADED_HEADER, "1");
  return { name: page.name, seo: seoFields(seo), sections, device: requestDevice(request) };
}
